# Bank zadań autorskich — etap 2: wypracowania (partia 1: starożytność, średniowiecze, nowożytność).
# Każde wypracowanie: temat w stylu CKE (teza + wymagane aspekty), modelowa odpowiedź (min. 300 słów)
# i omówienie (plan, typowe błędy). Dział „umiejetnosci” = wypowiedź argumentacyjna.
BANK = {}

M = 'Wypracowanie (wypowiedź argumentacyjna). Zadanie autorskie IndexLab w formacie egzaminu maturalnego od 2023 r. Twoja wypowiedź powinna liczyć minimum 300 wyrazów.'

BANK['umiejetnosci'] = [
 B('Wypracowanie — starożytność: demokracja ateńska', M,
   T('wypracowanie', 15, 'Demokracja ateńska w V w. p.n.e. była rządami całego społeczeństwa. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt polityczny, społeczny i kulturowy.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa tylko częściowo).\n\n'
     'Demokracja ateńska, ukształtowana po reformach Klejstenesa (508/507 p.n.e.) i rozwinięta za Peryklesa, uchodzi za kolebkę ustroju, w którym władzę sprawuje lud. Uważam jednak, że tylko w ograniczonym sensie można mówić o rządach całego społeczeństwa, bo prawa polityczne miała jedynie mniejszość mieszkańców Attyki.\n\n'
     'W aspekcie politycznym ustrój Aten był rzeczywiście bardzo demokratyczny — ale dla obywateli. Najważniejsze decyzje podejmowało zgromadzenie ludowe (eklezja), w którym mógł przemawiać i głosować każdy pełnoletni obywatel. Członków Rady Pięciuset i większość urzędników losowano, a o wygnaniu polityka groźnego dla demokracji decydował sąd skorupkowy (ostracyzm). Perykles wprowadził diety za udział w sądach i radzie, dzięki czemu z praw politycznych mogli korzystać także ubodzy obywatele.\n\n'
     'Aspekt społeczny pokazuje jednak granice tej demokracji. Obywatelami byli wyłącznie dorośli mężczyźni, których oboje rodzice pochodzili z Aten (prawo Peryklesa z 451 p.n.e.). Praw politycznych nie miały kobiety, metojkowie — wolni cudzoziemcy, często zamożni kupcy i rzemieślnicy — ani niewolnicy, których w Attyce było bardzo wielu. Szacuje się, że pełnię praw miało najwyżej kilkanaście procent mieszkańców.\n\n'
     'W aspekcie kulturowym demokracja sprzyjała udziałowi szerokich grup w życiu wspólnoty. Teatr, finansowany przez bogatych obywateli (choregia), był dostępny dla ludu, a ubożsi otrzymywali pieniądze na bilety. Tragedie Ajschylosa czy Sofoklesa i komedie Arystofanesa poruszały sprawy publiczne. Zarazem kultura polityczna Aten wyrastała z życia mężczyzn-obywateli: agora i zgromadzenie były dla nich, a nie dla kobiet czy niewolników.\n\n'
     'Można bronić tezy, wskazując, że na tle innych ustrojów starożytności — monarchii perskiej czy oligarchicznej Sparty, gdzie rządziła wąska grupa Spartiatów, a heloci byli całkowicie bezprawni — Ateny dawały głos niespotykanie szerokiej grupie ludzi, także najuboższym obywatelom. Ten argument pokazuje jednak raczej wyjątkowość Aten w ich epoce niż to, że rządziło w nich całe społeczeństwo.\n\n'
     'Podsumowując, demokracja ateńska była rządami ludu w rozumieniu starożytnych — czyli ogółu obywateli — i pod tym względem przewyższała inne ustroje swojej epoki. Nie była jednak rządami całego społeczeństwa, bo większość mieszkańców pozostawała poza wspólnotą polityczną.',
     'Plan: stanowisko „częściowo” → polityczny (eklezja, losowanie, ostracyzm, diety) → społeczny (kto NIE był obywatelem: kobiety, metojkowie, niewolnicy; prawo z 451 p.n.e.) → kulturowy (teatr, choregia, sprawy publiczne na scenie) → wniosek.\n\nTypowe błędy: utożsamianie demokracji ateńskiej z dzisiejszą (powszechne prawo wyborcze); brak faktów — samo „była demokratyczna” nie daje punktów; pominięcie jednego z trzech aspektów (to zawsze obniża ocenę w kryterium A).')),

 B('Wypracowanie — starożytność: pryncypat Augusta', M,
   T('wypracowanie', 15, 'Pryncypat Oktawiana Augusta był w istocie monarchią, choć zachowywał pozory republiki. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt ustrojowy, militarny i ideologiczno-propagandowy.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa).\n\n'
     'Po zwycięstwie pod Akcjum (31 p.n.e.) Oktawian stał się jedynym władcą państwa rzymskiego. Pamiętając los Cezara, zamordowanego w 44 p.n.e. za dążenie do jedynowładztwa, nie przyjął tytułu króla ani dyktatora. Uważam jednak, że stworzony przez niego pryncypat był w istocie monarchią ukrytą za republikańską fasadą.\n\n'
     'W aspekcie ustrojowym formalnie nic się nie zmieniło: działał senat, zgromadzenia i urzędy republikańskie. Oktawian w 27 p.n.e. ogłosił nawet „przywrócenie republiki”. W praktyce jednak skupił w swoich rękach władzę trybuna ludowego (prawo weta i nietykalność), władzę prokonsularną nad najważniejszymi prowincjami oraz tytuł princepsa — pierwszego wśród senatorów. Połączenie tych uprawnień w jednej osobie, na stałe, oznaczało koniec republikańskiej zasady kolegialności i kadencyjności.\n\n'
     'W aspekcie militarnym August kontrolował armię. Prowincje, w których stacjonowały legiony, podlegały bezpośrednio jemu, a żołnierze składali przysięgę na jego imię. Utworzył gwardię pretoriańską i zapewnił weteranom ziemię i pieniądze. Kto miał wojsko, ten rządził — a wojsko było lojalne wobec princepsa, nie wobec senatu.\n\n'
     'Także propaganda służyła budowie władzy jednostki. August przyjął przydomek „Augustus” (czcigodny), a po śmierci został ubóstwiony; na Wschodzie czczono go jak boga już za życia. Poeci, tacy jak Wergiliusz w „Eneidzie”, wywodzili ród Juliuszów od Eneasza, a pokój rzymski (pax Romana) przedstawiano jako dar princepsa. Najlepszym dowodem monarchicznego charakteru ustroju jest sukcesja: władzę po Auguście przejął jego pasierb Tyberiusz, a senat jedynie to zatwierdził.\n\n'
     'Zwolennicy przeciwnego poglądu mogą wskazać, że senat zachował realne znaczenie: zarządzał częścią prowincji, a jego członkowie obejmowali najważniejsze urzędy i dowództwa. August zabiegał o jego poparcie i unikał otwartego łamania tradycji. Świadczy to jednak bardziej o politycznej zręczności princepsa niż o istnieniu równowagi władz — ostateczne decyzje i tak należały do niego.\n\n'
     'Podsumowując, August zachował formy republiki, ale ich treść wypełnił własną władzą. Pryncypat był więc monarchią, a republikańskie instytucje — dekoracją, która miała uspokoić tradycyjne elity. Jego następcy nie musieli już nawet udawać, że jest inaczej.',
     'Plan: stanowisko „tak” → ustrojowy (instytucje działają, ale władza trybuńska + prokonsularna + princeps na stałe) → militarny (legiony podległe princepsowi, pretorianie, weterani) → propaganda (Augustus, kult, Wergiliusz, pax Romana) → najmocniejszy dowód: dziedziczenie władzy (Tyberiusz) → wniosek.\n\nTypowe błędy: mylenie pryncypatu z dominatem (Dioklecjan, III/IV w.); pisanie, że August był dyktatorem (odrzucił ten tytuł).')),

 B('Wypracowanie — średniowiecze: wyprawy krzyżowe', M,
   T('wypracowanie', 15, 'Wyprawy krzyżowe przyniosły Europie więcej korzyści niż strat. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt polityczny, gospodarczy i kulturowy.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa w odniesieniu do Europy Zachodniej, ale nie dla chrześcijańskiego Wschodu).\n\n'
     'Wyprawy krzyżowe, zapoczątkowane wezwaniem papieża Urbana II w Clermont (1095), miały odzyskać Ziemię Świętą. Choć ich cel religijny ostatecznie się nie powiódł — w 1291 r. upadła Akka, ostatnia twierdza krzyżowców — uważam, że dla Europy Zachodniej przyniosły więcej korzyści niż strat. Inaczej było jednak z chrześcijańskim Bizancjum.\n\n'
     'W aspekcie politycznym krucjaty wzmocniły autorytet papiestwa, które pokazało, że potrafi poruszyć rycerstwo całej Europy. Powstały zakony rycerskie (templariusze, joannici, Krzyżacy), a wyjazdy części rycerstwa ograniczyły wewnętrzne wojny feudalne. Stratą była natomiast IV krucjata (1204), w której krzyżowcy złupili Konstantynopol — osłabione Bizancjum nie zdołało później obronić się przed Turkami (upadek w 1453 r.), a rozłam między Kościołami się pogłębił.\n\n'
     'W aspekcie gospodarczym krucjaty ożywiły handel lewantyński. Wenecja i Genua przewoziły krzyżowców i zdobyły faktorie na Wschodzie, a do Europy napływały przyprawy, jedwab, cukier i barwniki. Rozwój handlu sprzyjał rozwojowi miast i gospodarki pieniężnej, a zakon templariuszy stworzył system przekazów pieniężnych. Kosztem były ogromne wydatki i śmierć wielu ludzi — nie tylko rycerzy, ale też ubogich uczestników krucjaty ludowej.\n\n'
     'W aspekcie kulturowym Europejczycy zetknęli się z bardziej rozwiniętą wówczas cywilizacją arabską i bizantyjską. Przejmowano wiedzę medyczną, matematyczną (cyfry arabskie) i filozoficzną, choć dużą rolę w tym procesie odegrały też Hiszpania i Sycylia. Krucjaty miały też ciemną stronę: towarzyszyły im pogromy Żydów w miastach nadreńskich i wzrost nietolerancji religijnej.\n\n'
     'Przeciwnicy tezy słusznie zauważają, że wiele z tych zmian zaszłoby i bez krucjat: handel z Lewantem istniał już wcześniej, a rozwój miast wynikał przede wszystkim z postępu w rolnictwie i wzrostu liczby ludności. Krucjaty raczej przyspieszyły istniejące procesy, niż je wywołały. Nie zmienia to jednak bilansu: dla Europy Zachodniej były one czynnikiem rozwoju, a nie hamulcem.\n\n'
     'Podsumowując, dla Europy Zachodniej krucjaty były impulsem rozwoju politycznego, gospodarczego i kulturowego, więc teza jest w dużej mierze prawdziwa. Trzeba jednak pamiętać o ich kosztach ludzkich i o tym, że dla Bizancjum okazały się katastrofą.',
     'Plan: stanowisko „tak, ale…” → polityczny (papiestwo, zakony, IV krucjata jako strata) → gospodarczy (handel lewantyński, Wenecja i Genua, miasta, koszty) → kulturowy (wiedza arabska, ale pogromy i nietolerancja) → wniosek z rozróżnieniem Zachód/Bizancjum.\n\nTypowe błędy: przypisywanie krucjatom całego przepływu wiedzy arabskiej (ważniejsza była Hiszpania); brak dat — minimum: 1095/1096, 1099, 1204, 1291.')),

 B('Wypracowanie — średniowiecze: Kazimierz Wielki', M,
   T('wypracowanie', 15, 'Panowanie Kazimierza Wielkiego było okresem przełomu w dziejach Polski. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji politykę zagraniczną, politykę wewnętrzną i gospodarkę.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa).\n\n'
     'Kazimierz Wielki objął w 1333 r. królestwo zjednoczone przez ojca, Władysława Łokietka, ale słabe, otoczone wrogami i zróżnicowane wewnętrznie. Po 37 latach panowania pozostawił państwo powiększone, sprawnie zarządzane i bogatsze. Uważam, że jego rządy były przełomem: przekształciły Polskę z luźnego zbioru dzielnic w nowoczesną monarchię stanową.\n\n'
     'W polityce zagranicznej Kazimierz zastąpił wojny dyplomacją. Na zjeździe w Wyszehradzie i w Trenczynie (1335) zrzekł się Śląska, ale uzyskał rezygnację Jana Luksemburskiego z pretensji do korony polskiej. Pokój kaliski z Krzyżakami (1343) przywrócił Polsce Kujawy i ziemię dobrzyńską. Zyskane bezpieczeństwo pozwoliło na ekspansję na wschód — przyłączenie Rusi Halickiej, co otworzyło Polsce drogę na wschód i zapowiadało przyszłą politykę jagiellońską. Zjazd monarchów w Krakowie (1364) pokazał nową pozycję Polski w Europie.\n\n'
     'W polityce wewnętrznej król ujednolicał państwo. Wydał statuty wiślicko-piotrkowskie, porządkujące prawo w Małopolsce i Wielkopolsce, rozwinął administrację starostów podległych królowi, a w 1364 r. założył Akademię Krakowską, kształcącą prawników dla państwa. Wzmocnił obronność, budując lub rozbudowując dziesiątki zamków i murów miejskich — stąd powiedzenie, że „zastał Polskę drewnianą, a zostawił murowaną”.\n\n'
     'W gospodarce Kazimierz wspierał lokacje miast i wsi na prawie niemieckim, zakładał nowe miasta (np. Kazimierz pod Krakowem), dbał o szlaki handlowe i zwiększył dochody z kopalń soli w Wieliczce i Bochni. Przyjmował też Żydów wypędzanych z Europy Zachodniej, potwierdzając i rozszerzając statut kaliski, co ożywiło handel i rzemiosło.\n\n'
     'Można wskazać, że nie wszystkie decyzje króla były trwałym sukcesem. Zrzeczenie się Śląska i Pomorza Gdańskiego oznaczało rezygnację z ziem zamieszkanych przez ludność polską, a jego następcy dopiero po stu latach odzyskali Pomorze. Były to jednak ustępstwa przemyślane: dawały pokój potrzebny do odbudowy państwa i nie zamykały drogi do późniejszych roszczeń.\n\n'
     'Podsumowując, teza jest prawdziwa: po Kazimierzu Polska była większa, bezpieczniejsza, lepiej rządzona i zamożniejsza. Jedynym poważnym ograniczeniem był brak męskiego potomka, co wymusiło sukcesję andegaweńską i pierwszy przywilej generalny dla szlachty (Koszyce, 1374).',
     'Plan: stanowisko „tak” → zagraniczna (Wyszehrad/Trenczyn 1335, Kalisz 1343, Ruś Halicka, zjazd 1364) → wewnętrzna (statuty, starostowie, Akademia 1364, zamki) → gospodarka (lokacje, sól, szlaki, Żydzi) → wniosek + jedno ograniczenie.\n\nTypowe błędy: przypisywanie Kazimierzowi odzyskania Pomorza Gdańskiego (stało się to w 1466 r.); wyliczanie faktów bez wyjaśnienia, dlaczego to „przełom”.')),

 B('Wypracowanie — średniowiecze i nowożytność: unia polsko-litewska', M,
   T('wypracowanie', 15, 'Unia polsko-litewska w latach 1385–1569 przyniosła obu państwom więcej korzyści niż strat. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt polityczny, militarny i kulturowy.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa, choć korzyści rozkładały się nierówno).\n\n'
     'Unia w Krewie (1385) połączyła dwa państwa o odmiennej religii, ustroju i kulturze. Przez prawie dwa stulecia związek ten pogłębiano: w Wilnie i Radomiu (1401), w Horodle (1413), aż po unię lubelską (1569), która stworzyła Rzeczpospolitą Obojga Narodów. Uważam, że unia przyniosła obu stronom więcej korzyści niż strat, choć z czasem Korona zyskiwała więcej niż Litwa.\n\n'
     'W aspekcie militarnym unia pozwoliła pokonać wspólnego wroga — zakon krzyżacki. Zwycięstwo pod Grunwaldem (1410), a później wojna trzynastoletnia i II pokój toruński (1466) przywróciły Polsce Pomorze Gdańskie. Dla Litwy unia była też oparciem w walkach z rosnącym w siłę Państwem Moskiewskim — w czasie wojny inflanckiej (1558–1570) to zagrożenie skłoniło Litwinów do zgody na ściślejszy związek.\n\n'
     'W aspekcie politycznym unia uczyniła z państwa Jagiellonów jedną z największych potęg Europy Środkowej; w końcu XV w. dynastia rządziła także w Czechach i na Węgrzech. Szlachta polska i litewska zbliżyły się dzięki wspólnym przywilejom (Horodło). Kosztem dla Litwy były jednak straty w 1569 r.: w trakcie sejmu lubelskiego Zygmunt August przyłączył do Korony Podlasie, Wołyń i Kijowszczyznę, a Litwa straciła część samodzielności.\n\n'
     'W aspekcie kulturowym unia oznaczała chrystianizację Litwy (1387) i wejście jej w krąg kultury łacińskiej. Litewskie elity przyjmowały język polski i polskie wzorce życia szlacheckiego, korzystały z Akademii Krakowskiej. Ceną była polonizacja bojarów i stopniowe zanikanie odrębności kulturowej litewskich elit, co w XIX w. litewski ruch narodowy oceniał krytycznie.\n\n'
     'Krytycy unii zwracają uwagę, że związek wciągał Polskę w konflikty litewskie z Moskwą, a Litwę — w polską rywalizację z zakonem i Habsburgami. Sami Litwini na sejmie lubelskim długo opierali się ściślejszemu związkowi i część posłów opuściła obrady w proteście. Te koszty były jednak mniejsze niż korzyść płynąca z bezpieczeństwa wobec Krzyżaków i Moskwy.\n\n'
     'Podsumowując, w perspektywie XV i XVI w. unia przyniosła obu państwom bezpieczeństwo, sukcesy militarne i pozycję międzynarodową. Teza jest więc prawdziwa, choć z czasem to Korona stawała się w związku stroną silniejszą.',
     'Plan: stanowisko „tak, ale nierówno” → militarny (Grunwald, 1466, Moskwa) → polityczny (potęga Jagiellonów, Horodło, ale straty Litwy w 1569) → kulturowy (chrzest 1387, łacińska Europa, ale polonizacja elit) → wniosek.\n\nTypowe błędy: traktowanie unii jako jednego wydarzenia (trzeba pokazać etapy); pomijanie perspektywy litewskiej.')),

 B('Wypracowanie — nowożytność: reformacja', M,
   T('wypracowanie', 15, 'Reformacja w XVI w. była przede wszystkim zjawiskiem religijnym. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt religijny, polityczny i społeczny.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa tylko częściowo — reformacja miała równie ważne przyczyny i skutki polityczne).\n\n'
     'Reformacja rozpoczęła się w 1517 r., gdy Marcin Luter ogłosił 95 tez przeciw odpustom. W ciągu kilkudziesięciu lat chrześcijaństwo zachodnie rozpadło się na wiele wyznań. Uważam, że reformacja nie była przede wszystkim zjawiskiem religijnym — jej sukces wynikał w równym stopniu z interesów politycznych i społecznych.\n\n'
     'Nie można oczywiście lekceważyć aspektu religijnego. Reformatorzy krytykowali sprzedaż odpustów, bogactwo i zeświecczenie duchowieństwa, a ich nauka (zbawienie przez wiarę, autorytet Biblii, kapłaństwo powszechne) odpowiadała na prawdziwe potrzeby duchowe wiernych. Luter przetłumaczył Biblię na niemiecki, a Kalwin rozwinął naukę o predestynacji.\n\n'
     'Aspekt polityczny był jednak decydujący dla sukcesu reformacji. Luter przetrwał dzięki ochronie elektora saskiego Fryderyka Mądrego. Książęta Rzeszy przechodzili na luteranizm, bo pozwalało im to przejąć majątki kościelne i uniezależnić się od cesarza; pokój augsburski (1555) z zasadą cuius regio, eius religio przyznał wybór wyznania władcom, a nie wiernym. W Anglii Henryk VIII zerwał z Rzymem z powodu sporu o unieważnienie małżeństwa, a Akt supremacji (1534) uczynił króla głową Kościoła. Albrecht Hohenzollern wykorzystał luteranizm do sekularyzacji zakonu krzyżackiego (1525).\n\n'
     'W aspekcie społecznym reformacja wyrażała napięcia epoki. Mieszczanie popierali kalwinizm, który cenił pracę i oszczędność; chłopi niemieccy, powołując się na hasła religijne, wywołali wojnę chłopską (1524–1525) — Luter wezwał wtedy książąt do jej stłumienia. W Rzeczypospolitej szlachta chętnie przyjmowała kalwinizm, bo osłabiał wpływy duchowieństwa i sądów kościelnych.\n\n'
     'Zwolennicy tezy mogą przypomnieć, że wielu ludzi ryzykowało życie i majątek dla nowej wiary, a przywódcy reformacji, jak Luter czy Kalwin, kierowali się przede wszystkim przekonaniami religijnymi. To prawda w odniesieniu do samych reformatorów i części wiernych. Jednak o tym, które kraje przyjęły protestantyzm, a które pozostały katolickie, decydowali głównie władcy i ich interesy.\n\n'
     'Podsumowując, reformacja zaczęła się od pytań religijnych, ale o jej przebiegu i zasięgu przesądziły interesy władców i różnych grup społecznych. Teza jest więc tylko częściowo prawdziwa: religia była iskrą, ale paliwem — polityka i interesy społeczne.',
     'Plan: stanowisko „częściowo” → religijny (odpusty, sola fide, Biblia, Kalwin) → polityczny (książęta, 1555, Henryk VIII 1534, Albrecht 1525) → społeczny (mieszczanie, wojna chłopska, szlachta polska) → wniosek.\n\nTypowe błędy: opisywanie tylko poglądów Lutra; pomijanie przykładów spoza Niemiec. Uwaga: przy tezie z „przede wszystkim” najbezpieczniej zająć stanowisko zniuansowane.')),

 B('Wypracowanie — nowożytność: Rzeczpospolita w XVII w.', M,
   T('wypracowanie', 15, 'XVII wiek był dla Rzeczypospolitej okresem upadku. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt międzynarodowy, ustrojowy i gospodarczy.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa, zwłaszcza dla drugiej połowy wieku).\n\n'
     'Na początku XVII w. Rzeczpospolita była jednym z największych państw Europy, a jej wojska zajęły nawet Moskwę (1610). Sto lat później była krajem zniszczonym, słabym i zależnym od sąsiadów. Uważam, że XVII w. był okresem upadku, choć jego źródłem były nie tyle pojedyncze klęski, ile trwałe słabości ustroju i gospodarki.\n\n'
     'W aspekcie międzynarodowym pierwsza połowa wieku przyniosła jeszcze sukcesy: Kircholm (1605), Kłuszyn (1610), obronę Chocimia (1621). Druga połowa to jednak pasmo wojen na kilku frontach. Powstanie Chmielnickiego (1648), potop szwedzki (1655–1660) i wojna z Moskwą przyniosły straty: utratę Kijowa i lewobrzeżnej Ukrainy (Andruszowo 1667), niezależność Prus Książęcych (1657) i chwilową utratę Podola (Buczacz 1672). Odsiecz wiedeńska (1683) była wielkim triumfem, ale nie odwróciła trendu.\n\n'
     'W aspekcie ustrojowym zasady demokracji szlacheckiej zaczęły paraliżować państwo. W 1652 r. po raz pierwszy zerwano sejm na podstawie liberum veto. Rosła rola magnatów, którzy prowadzili własną politykę i kupowali głosy szlachty; rokosz Lubomirskiego (1665–1666) pokazał, że reforma ustroju jest niemożliwa. Król miał coraz mniej władzy, a skarb i stałe wojsko pozostawały zbyt małe.\n\n'
     'W aspekcie gospodarczym wojny, zwłaszcza potop, zniszczyły miasta i wsie, a liczba ludności spadła. Gospodarka folwarczno-pańszczyźniana, która w XVI w. przynosiła zyski z eksportu zboża, w XVII w. przestała się opłacać — ceny zboża spadły, a szlachta rekompensowała to zwiększaniem pańszczyzny. Miasta podupadały, a rzemiosło nie mogło konkurować z zachodnim.\n\n'
     'Można bronić przeciwnego poglądu: w XVII w. Rzeczpospolita wciąż odnosiła wielkie zwycięstwa, a jej kultura barokowa, architektura i sarmacka obyczajowość przeżywały rozkwit. Państwo przetrwało potop i odzyskało Podole w Karłowicach (1699). Świadczy to o jego odporności, ale nie zmienia faktu, że na przełomie wieków było znacznie słabsze niż na początku stulecia.\n\n'
     'Podsumowując, XVII w. był dla Rzeczypospolitej okresem upadku, choć nie od razu: pierwsze dekady to jeszcze potęga, a załamanie przyszło po 1648 r. i miało przyczyny głębsze niż same wojny. To właśnie te słabości wykorzystali sąsiedzi w XVIII w.',
     'Plan: stanowisko „tak, zwłaszcza po 1648” → międzynarodowy (sukcesy do 1621, potem 1648, potop, Andruszowo, Prusy 1657, Buczacz) → ustrojowy (liberum veto 1652, magnateria, rokosz) → gospodarczy (zniszczenia, kryzys folwarku, upadek miast) → wniosek z periodyzacją.\n\nTypowe błędy: pisanie, że cały wiek był pasmem klęsk (pomijanie sukcesów z początku wieku osłabia argumentację); mylenie dat traktatów.')),

 B('Wypracowanie — nowożytność: odkrycia geograficzne', M,
   T('wypracowanie', 15, 'Wielkie odkrycia geograficzne przełomu XV i XVI w. przyniosły Europejczykom korzyści, a ludom Ameryki — katastrofę. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt gospodarczy, demograficzny i kulturowy.',
     'Modelowa odpowiedź (stanowisko: teza jest w przeważającej mierze prawdziwa).\n\n'
     'Wyprawy Kolumba (1492), Vasco da Gamy (1498) i Magellana (1519–1522) połączyły kontynenty, które wcześniej rozwijały się osobno. Uważam, że dla ludów Ameryki skutki tego spotkania były katastrofalne, a Europejczycy, choć nie wszyscy w równym stopniu, odnieśli z niego ogromne korzyści.\n\n'
     'W aspekcie gospodarczym Europa zyskała nowe rynki, surowce i rośliny: ziemniaki, kukurydzę, pomidory, kakao, tytoń. Ze złóż Potosí i Meksyku do Hiszpanii płynęło srebro, co wywołało rewolucję cen. Na handlu oceanicznym bogaciły się Portugalia, Hiszpania, a potem Niderlandy i Anglia, a centrum gospodarcze Europy przesunęło się znad Morza Śródziemnego nad Atlantyk. Jednocześnie Indianie zostali zmuszeni do pracy w kopalniach i na plantacjach (system encomienda), a do Ameryki zaczęto przywozić niewolników z Afryki.\n\n'
     'W aspekcie demograficznym skutki dla Ameryki były tragiczne. Choroby przywleczone z Europy — ospa, odra, grypa — na które Indianie nie mieli odporności, w ciągu stulecia zabiły zdecydowaną większość ludności rdzennej. Do tego doszły wojny podboju (Cortés i upadek Azteków 1519–1521, Pizarro i Inkowie) oraz wyniszczająca praca przymusowa. Europa nie poniosła porównywalnych strat; przeciwnie, nowe rośliny uprawne pomogły w kolejnych stuleciach wyżywić rosnącą ludność.\n\n'
     'W aspekcie kulturowym odkrycia zmieniły europejskie wyobrażenie o świecie i przyspieszyły rozwój nauki (kartografia, nawigacja, dowód kulistości Ziemi). Dla cywilizacji Azteków, Majów i Inków oznaczały zniszczenie świątyń, miast i ksiąg oraz przymusową chrystianizację. Niektórzy Europejczycy, jak dominikanin Bartolomé de Las Casas, protestowali przeciw okrucieństwom, ale nie powstrzymali procesu.\n\n'
     'Trzeba też zaznaczyć, że wymiana między kontynentami nie płynęła tylko w jedną stronę. Do Ameryki trafiły konie, bydło, pszenica i trzcina cukrowa, które zmieniły tamtejsze rolnictwo, a z czasem także życie części ludów indiańskich, np. na prerii. Te zmiany nie równoważyły jednak katastrofy demograficznej, która dotknęła rdzenną ludność.\n\n'
     'Podsumowując, odkrycia geograficzne były dla Europy początkiem dominacji nad światem, a dla rdzennych ludów Ameryki — katastrofą demograficzną i kulturową. Teza jest więc prawdziwa, choć korzyści w samej Europie rozkładały się nierówno, a koszty ponieśli też porywani w niewolę Afrykańczycy.',
     'Plan: stanowisko „tak” → gospodarczy (rośliny, srebro, rewolucja cen, przesunięcie handlu, ale encomienda i niewolnictwo) → demograficzny (choroby, podbój, praca przymusowa) → kulturowy (nauka i obraz świata vs. zniszczenie kultur, Las Casas) → wniosek.\n\nTypowe błędy: podawanie samych wypraw i dat bez skutków; brak przykładów konkretnych cywilizacji.')),
]
